-- =============================================================================
-- 534 — LE CAHIER D'EXERCICES DE 1RE (partie 22)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 534 --niveau 1re --fichiers hggsp.n3,histoire-geo-techno.n1,histoire-geo-techno.n2 --suffixe 22 > supabase/contenu/534_exercices_1re_22.sql
--
-- 87 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   hggsp.n3                21 exercices · 7 chapitres
--   histoire-geo-techno.n1  33 exercices · 11 chapitres
--   histoire-geo-techno.n2  33 exercices · 11 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('1dc8244c-1c84-5ca7-a8df-beed9c703000'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les grandes dates du réseau","competence":"se-reperer-temps","situation":"Nadia prépare une fiche sur l’histoire d’Internet. Elle a dessiné une frise : il lui reste à la lire pour y placer les bonnes étapes.","documents":[{"id":"frise","type":"frise","titre":"D’ARPANET aux plateformes","source":"Frise réalisée d’après le cours.","debut":1960,"fin":2020,"pas":10,"periodes":[{"id":"z1","debut":1990,"fin":1999,"nom":"Ouverture au public","teinte":"ambre"},{"id":"z2","debut":2000,"fin":2009,"nom":"Web social","teinte":"rose"},{"id":"z3","debut":2010,"fin":2020,"nom":"Internet mobile","teinte":"turquoise"}],"evenements":[{"id":"z4","date":1969,"nom":"ARPANET"},{"id":"z5","date":1989,"nom":"Web au CERN"}]}],"questions":[{"enonce":"Touche la période où chacun devient producteur de contenus.","aide":"Pense aux blogs et aux réseaux où l’on publie soi-même.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche la période où les plateformes deviennent le principal accès à l’information.","aide":"C’est la période la plus récente de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent les premiers nœuds d’ARPANET du Web inventé au CERN ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi ARPANET est-il conçu comme un réseau décentralisé ?","aide":"Souviens-toi de l’origine militaire du projet.","type":"choix","options":[{"id":"a","texte":"Pour continuer de fonctionner si l’un de ses nœuds est détruit"},{"id":"b","texte":"Pour permettre aux entreprises de vendre de la publicité"},{"id":"c","texte":"Pour relier d’abord les écoles avant les universités"},{"id":"d","texte":"Pour que chaque utilisateur puisse publier ses propres contenus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Dans les années 2000 naît le **web social** : chacun peut publier, et plus seulement lire."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Dans les années 2010, avec l’**Internet mobile**, les plateformes deviennent les principaux points d’accès à l’information."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 ans","explication":"1989 − 1969 = **20 ans** entre ARPANET et le World Wide Web."},{"cle":{"type":"choix","ids":["a"]},"explication":"ARPANET est né d’un projet militaire américain : un réseau **décentralisé** survit à la destruction d’un de ses nœuds."}]$ex$::jsonb),
  ('1dc8244c-1c84-5ca7-a8df-beed9c703000'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux fils d’actualité pour un même débat","competence":"lire-tableau","situation":"Camille et Ismaël suivent le même débat sur un projet de piste cyclable (cas imaginé). Chacun a regardé les 20 premières publications de son fil.","documents":[{"id":"fils","type":"tableau","titre":"Les 20 premières publications du fil de chacun","source":"Chiffres imaginés pour l’exercice.","colonnes":["Lecteur","Favorables au projet","Opposées au projet","Total"],"lignes":[["Camille",17,3,20],["Ismaël",4,16,20]],"enteteLignes":true}],"questions":[{"enonce":"Quelle part des publications du fil de Camille est favorable au projet ?","aide":"Divise le nombre de publications favorables par le total, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Touche la case qui indique ce que voit le plus souvent Ismaël.","aide":"Compare les deux cases de la ligne d’Ismaël.","type":"zone","document":"fils","multiple":false},{"enonce":"Comment s’appelle l’effet qui fait que chacun est surtout exposé à ce qui confirme ses convictions ?","aide":"Les deux fils sont très différents alors que le débat est le même.","type":"choix","options":[{"id":"a","texte":"La fracture numérique"},{"id":"b","texte":"La bulle de filtres"},{"id":"c","texte":"Le monopole des médias"},{"id":"d","texte":"L’infobésité"}],"multiple":false},{"enonce":"Associe chaque effet à sa définition.","aide":"Chaque effet a un mot-clé : confirmer, abondance, réagir, critique.","type":"association","gauche":[{"id":"g0","texte":"Bulle de filtres"},{"id":"g1","texte":"Infobésité"},{"id":"g2","texte":"Viralité"},{"id":"g3","texte":"Fracture cognitive"}],"droite":[{"id":"d0","texte":"Manque de capacité à user du réseau de façon critique"},{"id":"d1","texte":"L’abondance rend le tri plus difficile que la recherche"},{"id":"d2","texte":"Ce qui circule est ce qui fait réagir"},{"id":"d3","texte":"On est surtout exposé à ce qui confirme ses idées"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":85,"tolerance":0},"affichage":"85 %","explication":"17 ÷ 20 = 0,85, soit **85 %** de publications favorables."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Ismaël voit surtout des publications **opposées** au projet : 16 sur 20."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est la **bulle de filtres** : l’algorithme compose un flux qui conforte chacun, et la contradiction se raréfie."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"Bulle de filtres = ce qui **confirme** ; infobésité = **abondance** ; viralité = ce qui fait **réagir** ; fracture cognitive = absence de **regard critique**."}]$ex$::jsonb),
  ('1dc8244c-1c84-5ca7-a8df-beed9c703000'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pourquoi la rumeur voyage plus vite","competence":"analyser-document","situation":"Léo a retrouvé la note interne d’une plateforme imaginaire, Fluxo, et un graphique sur la circulation de deux types de contenus. Il veut comprendre ce qui est mis en avant.","documents":[{"id":"note","type":"texte","genre":"article","titre":"Note interne de la plateforme Fluxo","auteur":"Texte écrit pour l’exercice : plateforme imaginaire","blocs":["Fluxo est gratuite : elle se finance en vendant de la publicité aux annonceurs.","Plus un utilisateur reste longtemps, plus il voit d’annonces. L’algorithme recommande donc d’abord les contenus qui font le plus réagir.","Il ne vérifie pas les informations avant de les recommander."]},{"id":"partages","type":"graphique","forme":"barres","titre":"Partages moyens par publication","source":"Chiffres imaginés pour l’exercice.","categories":["Information vérifiée","Rumeur sensationnelle"],"series":[{"nom":"Partages","valeurs":[120,480],"teinte":"violet"}],"axeY":{"titre":"Partages","unite":"par publication","min":0,"max":500,"pas":100},"valeurs":false}],"questions":[{"enonce":"Touche le mot qui explique de quoi vit la plateforme.","aide":"Le premier paragraphe dit comment elle se finance.","type":"zone","document":"note","multiple":false},{"enonce":"Touche la barre du contenu qui circule le plus.","aide":"Cherche la barre la plus haute.","type":"zone","document":"partages","multiple":false},{"enonce":"Combien de fois la rumeur est-elle plus partagée que l’information vérifiée ?","aide":"Divise la valeur de la rumeur par celle de l’information vérifiée.","type":"nombre","unite":"fois"},{"enonce":"Quel lien peut-on faire entre la note et le graphique ?","aide":"Relis le deuxième paragraphe de la note, puis regarde quelle barre est la plus haute.","type":"choix","options":[{"id":"a","texte":"Les annonceurs paient pour diffuser des informations vérifiées"},{"id":"b","texte":"L’algorithme favorise ce qui fait réagir, pas ce qui est vérifié"},{"id":"c","texte":"La plateforme supprime les rumeurs avant qu’elles circulent"},{"id":"d","texte":"Les utilisateurs partagent surtout les contenus les plus sérieux"}],"multiple":false},{"enonce":"Complète le renversement décisif.","aide":"L’information est devenue presque illimitée : le problème, c’est de la trier.","type":"trous","segments":["L’enjeu n’est plus l’",0," à l’information, mais sa ",1," et sa vérification."],"banque":["accès","diffusion","hiérarchisation","gratuité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"La gratuité n’est qu’apparente : la plateforme vit de la **publicité**, donc de l’attention et des données de ses utilisateurs."},{"cle":{"type":"zone","ids":["k1"]},"explication":"La **rumeur sensationnelle** est la plus partagée : 480 partages en moyenne."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 fois","explication":"480 ÷ 120 = **4 fois** plus de partages."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un algorithme qui cherche à faire **réagir** pousse ce qui est viral. La **viralité** ne mesure pas la vérification."},{"cle":{"type":"trous","trous":[["acces"],["hierarchisation"]]},"affichage":"accès · hiérarchisation","explication":"L’accès est devenu presque illimité ; l’enjeu est désormais la **hiérarchisation** et la **vérification**, que le lecteur doit en partie assurer lui-même."}]$ex$::jsonb),
  ('84e3cf31-af07-5f97-a91b-d66c68789873'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une affaire en quatre dates","competence":"se-reperer-temps","situation":"Inès prépare un exposé sur l’affaire Dreyfus. Sa frise ne retient que quatre moments : elle doit s’y retrouver avant de raconter l’histoire.","documents":[{"id":"frise","type":"frise","titre":"De la condamnation à la réhabilitation","source":"Frise réalisée d’après le cours.","debut":1890,"fin":1910,"pas":5,"evenements":[{"id":"z1","date":1894,"nom":"Condamnation"},{"id":"z2","date":1896,"nom":"Picquart"},{"id":"z3","date":1898,"nom":"« J’accuse… ! »"},{"id":"z4","date":1906,"nom":"Réhabilitation"}]}],"questions":[{"enonce":"Touche l’événement qui correspond à la lettre ouverte de Zola dans L’Aurore.","aide":"Cherche le titre de la lettre.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années s’écoulent entre la condamnation de Dreyfus et sa réhabilitation ?","aide":"Soustrais la date de la condamnation à celle de la réhabilitation.","type":"nombre","unite":"ans"},{"enonce":"Combien d’années séparent la découverte de Picquart de la lettre de Zola ?","aide":"Lis les années de ces deux événements sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Entre 1896 et 1898, que se passe-t-il pour que Zola prenne la plume ?","aide":"Pense à ce qui arrive à Esterhazy en janvier 1898.","type":"choix","options":[{"id":"a","texte":"Dreyfus est gracié et revient en France"},{"id":"b","texte":"L’état-major étouffe l’affaire et Esterhazy est acquitté"},{"id":"c","texte":"Le colonel Picquart est élu président de la République"},{"id":"d","texte":"La loi de séparation des Églises et de l’État est votée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **13 janvier 1898**, Zola publie « J’accuse… ! » à la une de *L’Aurore*."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 ans","explication":"1906 − 1894 = **12 ans** pour que l’erreur soit officiellement réparée."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 ans","explication":"1898 − 1896 = **2 ans** : Picquart a trouvé le vrai auteur du bordereau, mais l’état-major a étouffé l’affaire."},{"cle":{"type":"choix","ids":["b"]},"explication":"En janvier 1898, l’état-major **étouffe l’affaire** : Esterhazy, le vrai auteur du bordereau, est acquitté. Zola réagit deux jours plus tard."}]$ex$::jsonb),
  ('84e3cf31-af07-5f97-a91b-d66c68789873'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre à la une de L’Aurore","competence":"analyser-texte","situation":"Samir a trouvé la fiche d’identité de la une du 13 janvier 1898 et un résumé de la lettre qu’elle porte. Il cherche pourquoi Zola prend un tel risque.","documents":[{"id":"une","type":"fiche","modele":"affiche","entete":"L’Aurore","sousTitre":"13 janvier 1898","emoji":"📰","lignes":[{"texte":"À la une","valeur":"Lettre ouverte au président de la République"},{"texte":"Auteur","valeur":"Émile Zola"},{"texte":"Titre trouvé par","valeur":"Clemenceau","id":"z1"},{"texte":"Tirage du jour","valeur":"300 000 exemplaires"}],"pied":"Fiche résumée d’après le cours"},{"id":"resume","type":"texte","genre":"article","titre":"Ce que dit la lettre","auteur":"Résumé rédigé pour l’exercice","blocs":["Zola affirme qu’un innocent a été condamné en 1894 et que le véritable auteur du bordereau, le commandant Esterhazy, vient d’être acquitté.","Il nomme les responsables, sachant qu’il s’expose à un procès en diffamation. C’est ce qu’il cherche : que l’affaire soit débattue au grand jour, de façon contradictoire."]}],"questions":[{"enonce":"Touche la ligne qui dit qui a trouvé le titre de la lettre.","aide":"Zola n’est pas l’auteur du titre.","type":"zone","document":"une","multiple":false},{"enonce":"Touche le nom du véritable auteur du bordereau.","aide":"Il vient d’être acquitté.","type":"zone","document":"resume","multiple":false},{"enonce":"Touche le mot qui désigne le procès auquel Zola s’expose volontairement.","aide":"Zola nomme des personnes : la loi punit ce délit.","type":"zone","document":"resume","multiple":false},{"enonce":"Pourquoi Zola cherche-t-il à être poursuivi ?","aide":"Relis la dernière phrase du résumé.","type":"choix","options":[{"id":"a","texte":"Pour forcer un débat contradictoire public"},{"id":"b","texte":"Pour être élu député à Paris"},{"id":"c","texte":"Pour obtenir l’interdiction du journal concurrent"},{"id":"d","texte":"Pour échapper à une condamnation plus lourde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est **Clemenceau** qui donne son titre à la lettre : « J’accuse… ! »."},{"cle":{"type":"zone","ids":["m19"]},"explication":"Le véritable auteur du bordereau est le commandant **Esterhazy**, découvert par Picquart en 1896."},{"cle":{"type":"zone","ids":["m37"]},"explication":"Zola s’expose à un procès en **diffamation**, car il nomme les responsables. C’est ce qu’il recherche."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un procès oblige à débattre **publiquement et de façon contradictoire** : c’est le moyen de rouvrir l’affaire."}]$ex$::jsonb),
  ('84e3cf31-af07-5f97-a91b-d66c68789873'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux éditoriaux, une même affaire","competence":"analyser-document","situation":"Lina fouille un grenier et trouve deux éditoriaux imaginés dans l’esprit de 1898, qui ne disent pas la même chose. Elle les confronte pour comprendre le rôle de la presse.","documents":[{"id":"a","type":"texte","genre":"article","titre":"Éditorial A","auteur":"Texte écrit pour l’exercice : aucun journal réel","blocs":["Le conseil de guerre a jugé : la chose est jugée.","Rouvrir l’affaire, c’est affaiblir l’armée devant l’Allemagne. Ceux qui réclament la révision divisent les Français au pire moment."]},{"id":"b","type":"texte","genre":"article","titre":"Éditorial B","auteur":"Texte écrit pour l’exercice : aucun journal réel","blocs":["Un homme est au bagne depuis 1894, condamné sur une pièce mince.","L’honneur de l’armée n’est pas de se taire : il est de reconnaître l’erreur. La vérité ne doit rien à l’état-major."]}],"questions":[{"enonce":"Range chaque argument dans l’éditorial qui le défend.","aide":"Un éditorial défend l’armée, l’autre défend la révision.","type":"categories","categories":[{"id":"c0","texte":"Éditorial A"},{"id":"c1","texte":"Éditorial B"}],"items":[{"id":"i0","texte":"Rouvrir l’affaire affaiblit l’armée"},{"id":"i1","texte":"L’honneur est de reconnaître l’erreur"},{"id":"i2","texte":"La condamnation repose sur une pièce mince"},{"id":"i3","texte":"La chose est jugée, il faut s’en tenir là"}]},{"enonce":"Touche le verbe qui dit ce que la révision ferait à l’armée selon l’éditorial A.","aide":"C’est le contraire de « renforcer ».","type":"zone","document":"a","multiple":false},{"enonce":"Que montre cette confrontation sur le rôle de la presse dans l’affaire ?","aide":"Deux journaux, deux versions du même fait.","type":"choix","options":[{"id":"a","texte":"Elle reste neutre et se contente de relayer les faits"},{"id":"b","texte":"Elle est contrôlée par un seul parti"},{"id":"c","texte":"Elle n’intéresse que les militaires"},{"id":"d","texte":"Elle est une puissance politique qui structure deux camps"}],"multiple":false},{"enonce":"Que permet la même liberté de la presse, d’après le bilan de l’affaire ?","aide":"Pense à La Libre Parole d’un côté, à Zola de l’autre.","type":"choix","options":[{"id":"a","texte":"La campagne de calomnie comme son démenti"},{"id":"b","texte":"Seulement la diffusion de fausses preuves"},{"id":"c","texte":"La suppression de tout débat public"},{"id":"d","texte":"Seulement la défense de l’innocent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"L’**éditorial A** protège l’institution militaire ; l’**éditorial B** réclame la révision au nom de la vérité."},{"cle":{"type":"zone","ids":["m15"]},"explication":"Pour l’auteur, rouvrir l’affaire reviendrait à **affaiblir** l’armée : l’argument de l’ordre contre celui de la vérité."},{"cle":{"type":"choix","ids":["d"]},"explication":"La presse **impose un sujet, structure deux camps et fait basculer l’opinion** : c’est une puissance politique."},{"cle":{"type":"choix","ids":["a"]},"explication":"La même liberté a permis la **calomnie** et son **démenti** : elle n’est pas neutre, mais elle est la condition pour qu’une erreur soit corrigée."}]$ex$::jsonb),
