  ('0a392ab1-c353-5406-a982-3f8b6b94ef86'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Quand la justice devient une arme","competence":"lire-graphique","situation":"Dans un pays imaginaire, des journalistes d’investigation se plaignent d’être attaqués en justice. Zoé compare des chiffres et classe des cas pour comprendre où s’arrête la liberté d’informer.","documents":[{"id":"baillons","type":"graphique","forme":"barres","titre":"Poursuites contre des journalistes d’investigation","source":"Chiffres imaginés pour l’exercice.","categories":["2019","2020","2021","2022","2023"],"series":[{"nom":"Poursuites","valeurs":[12,18,25,31,44],"teinte":"turquoise"}],"axeY":{"titre":"Poursuites","unite":"par an","min":0,"max":50,"pas":10},"axeX":{"titre":"Année"},"valeurs":false},{"id":"cas","type":"tableau","titre":"Quatre publications poursuivies","source":"Cas imaginés pour l’exercice.","colonnes":["Publication","Ce qu’elle contient"],"lignes":[["A","Accuse un maire de corruption, sans aucune preuve"],["B","Publie l’adresse et des photos de la famille d’un voisin"],["C","Appelle à s’en prendre à une communauté"],["D","Dévoile des documents secrets de la défense nationale"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’année où il y a eu le plus de poursuites.","aide":"Cherche la barre la plus haute.","type":"zone","document":"baillons","multiple":false},{"enonce":"De combien de poursuites par an le chiffre a-t-il augmenté entre 2019 et 2023 ?","aide":"Lis la barre de 2019 et celle de 2023, puis soustrais.","type":"nombre","unite":"poursuites"},{"enonce":"Une action en justice destinée à épuiser un journaliste plutôt qu’à obtenir gain de cause s’appelle…","aide":"Le nom évoque ce qu’on met sur une bouche.","type":"choix","options":[{"id":"a","texte":"Une lettre de cachet"},{"id":"b","texte":"Un secret d’instruction"},{"id":"c","texte":"Un droit de réponse"},{"id":"d","texte":"Une procédure-bâillon"}],"multiple":false},{"enonce":"Associe chaque publication à la limite de la liberté d’informer qu’elle met en jeu.","aide":"Demande-toi à chaque fois ce que la loi protège : un honneur, une intimité, des personnes visées, la sécurité du pays.","type":"association","gauche":[{"id":"g0","texte":"Publication A"},{"id":"g1","texte":"Publication B"},{"id":"g2","texte":"Publication C"},{"id":"g3","texte":"Publication D"}],"droite":[{"id":"d0","texte":"Diffamation : l’honneur"},{"id":"d1","texte":"Secret de la défense : la sécurité"},{"id":"d2","texte":"Incitation à la haine : l’ordre public"},{"id":"d3","texte":"Vie privée : l’intimité"}]},{"enonce":"Qui doit décider si une publication a franchi une de ces limites ?","aide":"Ces limites sont aussi celles qu’un pouvoir invoque pour restreindre.","type":"choix","options":[{"id":"a","texte":"L’administration"},{"id":"b","texte":"Le ministre"},{"id":"c","texte":"Le juge"},{"id":"d","texte":"Le propriétaire du journal"}],"multiple":false}]}$ex$::jsonb,
