  ('0a392ab1-c353-5406-a982-3f8b6b94ef86'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un pays libre sur le papier ?","competence":"analyser-document","situation":"Camille compare le discours officiel d’un pays imaginaire, l’Altavie, à des chiffres de 2023. Elle veut savoir si la liberté de l’information y est réelle ou seulement écrite.","documents":[{"id":"alt","type":"texte","genre":"article","titre":"L’Altavie vue de près","auteur":"Texte écrit pour l’exercice : pays imaginaire","blocs":["La Constitution d’Altavie proclame que la presse est libre. Les procès sont jugés par des tribunaux publics.","Pourtant, une loi punit la publication de « fausses nouvelles » sans jamais les définir. C’est le ministère de l’Intérieur, et non un juge, qui peut retirer sa carte de presse à un journaliste.","Trois groupes détiennent presque tous les journaux du pays."]},{"id":"chiffres","type":"tableau","titre":"L’Altavie en 2023","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Valeur"],"lignes":[["Journalistes poursuivis pour diffamation","14"],["Journalistes condamnés","1"],["Cartes de presse retirées par le ministère","9"],["Titres de presse détenus par trois groupes","80 %"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’autorité qui peut retirer la carte de presse, alors que ce devrait être un juge.","aide":"Cherche une administration dans le deuxième paragraphe.","type":"zone","document":"alt","multiple":false},{"enonce":"Combien de journalistes poursuivis n’ont pas été condamnés ?","aide":"Soustrais les condamnés aux poursuivis.","type":"nombre","unite":"journalistes"},{"enonce":"Range chaque élément : garantit-il la liberté de l’information ou la restreint-il ?","aide":"Un texte ou un tribunal protège ; un pouvoir flou ou concentré restreint.","type":"categories","categories":[{"id":"c0","texte":"Garantit"},{"id":"c1","texte":"Restreint"}],"items":[{"id":"i0","texte":"Le ministère retire des cartes de presse"},{"id":"i1","texte":"Trois groupes détiennent 80 % des titres"},{"id":"i2","texte":"Les procès se tiennent devant des tribunaux publics"},{"id":"i3","texte":"La Constitution proclame la presse libre"},{"id":"i4","texte":"Une loi punit des « fausses nouvelles » sans les définir"}]},{"enonce":"Que montre le rapport entre 14 poursuites et 1 condamnation ?","aide":"Une procédure peut être efficace même sans condamnation.","type":"choix","options":[{"id":"a","texte":"Une loi qui protège toujours les sources"},{"id":"b","texte":"Un journalisme sans aucune erreur"},{"id":"c","texte":"Des poursuites destinées à épuiser plutôt qu’à gagner"},{"id":"d","texte":"Une justice trop indulgente envers les médias"}],"multiple":false},{"enonce":"Que conclure sur la liberté de l’information en Altavie ?","aide":"Compare ce qui est écrit à ce qui est possible dans les faits.","type":"choix","options":[{"id":"a","texte":"Elle se mesure moins aux textes qu’à ce qu’on peut publier"},{"id":"b","texte":"Elle est totale, puisque des tribunaux existent"},{"id":"c","texte":"Elle est garantie, puisque la Constitution la proclame"},{"id":"d","texte":"Elle n’a aucun sens dans un pays imaginaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"C’est le **ministère** de l’Intérieur : une décision administrative, sans juge, est un signe de contrôle."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 journalistes","explication":"14 − 1 = **13 journalistes** poursuivis sans être condamnés : le signe d’une possible procédure-bâillon."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"La Constitution et les tribunaux publics **garantissent** ; les lois floues, le retrait administratif des cartes et la **concentration** des médias **restreignent**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Beaucoup de poursuites pour une seule condamnation : c’est la logique de la **procédure-bâillon**, qui use le journaliste plus qu’elle ne vise la victoire."},{"cle":{"type":"choix","ids":["a"]},"explication":"La liberté se mesure **moins aux textes qu’à ce qu’il est effectivement possible de publier** : l’Altavie la proclame mais la restreint."}]$ex$::jsonb),
  ('2ccd9285-da40-506f-91db-a2670cdb1779'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que disent les journaux, ce que voit le front","competence":"analyser-texte","situation":"Louise reçoit une lettre de son frère Paul, soldat en 1916. Il n’y reconnaît pas ce qu’il lit dans la presse.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Une lettre du front","auteur":"Lettre imaginée, écrite pour l’exercice","blocs":["Chère Louise, les journaux d’ici disent que nos pertes sont légères et que la victoire est proche.","Mais ici, avec les camarades, nous enterrons chaque jour ceux qui tombent, et aucun journal ne le dit. Nous ne croyons plus ce qu’on nous raconte.","Embrasse les enfants pour moi. Paul."]}],"questions":[{"enonce":"Touche les deux mots par lesquels la presse minimise la guerre.","aide":"Un mot parle des pertes, l’autre de la fin de la guerre.","type":"zone","document":"lettre","multiple":true},{"enonce":"Comment appelle-t-on cette propagande qui minimise les pertes et promet une victoire prochaine ?","aide":"L’expression est née pendant la Grande Guerre.","type":"choix","options":[{"id":"a","texte":"Le bourrage de crâne"},{"id":"b","texte":"Le samizdat"},{"id":"c","texte":"Le brouillage"},{"id":"d","texte":"La retouche de photographies"}],"multiple":false},{"enonce":"Quelle conséquence durable ce discours a-t-il sur les combattants ?","aide":"Relis la dernière phrase du deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"Un désintérêt pour la guerre"},{"id":"b","texte":"Une confiance accrue dans les journaux"},{"id":"c","texte":"Une envie d’écrire dans les journaux"},{"id":"d","texte":"Une défiance envers la presse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m17"]},"explication":"La presse parle de pertes **légères** et d’une victoire **proche** : c’est le procédé de propagande qu’on appelle le bourrage de crâne."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est le **bourrage de crâne** : minimiser les pertes, ridiculiser l’ennemi, promettre la victoire prochaine."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ce décalage entre le front et les journaux nourrit une **défiance durable** des combattants envers la presse."}]$ex$::jsonb),
  ('2ccd9285-da40-506f-91db-a2670cdb1779'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Par-dessus le rideau de fer","competence":"observer-schema","situation":"Pendant la guerre froide, une radio de l’Ouest veut atteindre des auditeurs de l’Est. Tomek, un élève, regarde le schéma d’un cours et en repère les acteurs.","documents":[{"id":"schema","type":"schema","titre":"Informer à l’Est pendant la guerre froide","source":"Schéma simplifié, d’après le cours.","largeur":340,"hauteur":280,"elements":[{"forme":"rect","x":15,"y":30,"l":100,"h":70,"arrondi":8,"teinte":"bleu","motif":"clair","id":"z1","zone":true},{"forme":"emoji","x":65,"y":55,"emoji":"📻","taille":30},{"forme":"texte","x":65,"y":90,"texte":"Radio de l’Ouest","taille":"petit","ancre":"milieu"},{"forme":"rect","x":225,"y":30,"l":100,"h":70,"arrondi":8,"teinte":"sable","motif":"clair","id":"z2","zone":true},{"forme":"emoji","x":275,"y":55,"emoji":"🏠","taille":30},{"forme":"texte","x":275,"y":90,"texte":"Auditeurs de l’Est","taille":"petit","ancre":"milieu"},{"forme":"rect","x":160,"y":15,"l":14,"h":100,"teinte":"brun","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":167,"y":130,"texte":"Rideau de fer","taille":"petit","ancre":"milieu"},{"forme":"ligne","de":[115,65],"a":[225,65],"fleche":"fin","teinte":"bleu"},{"forme":"rect","x":200,"y":160,"l":110,"h":40,"arrondi":8,"teinte":"corail","motif":"clair","id":"z4","zone":true,"texte":"Émetteur"},{"forme":"ligne","de":[255,160],"a":[255,106],"fleche":"fin","teinte":"corail","style":"pointilles"},{"forme":"rect","x":30,"y":215,"l":280,"h":45,"arrondi":8,"teinte":"ambre","motif":"clair","id":"z5","zone":true},{"forme":"emoji","x":65,"y":237,"emoji":"🧑","taille":28},{"forme":"emoji","x":170,"y":237,"emoji":"🧑","taille":28},{"forme":"emoji","x":275,"y":237,"emoji":"🧑","taille":28},{"forme":"ligne","de":[90,237],"a":[145,237],"fleche":"fin"},{"forme":"ligne","de":[195,237],"a":[250,237],"fleche":"fin"},{"forme":"texte","x":170,"y":207,"texte":"Textes recopiés à la main","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Touche l’émetteur dont les ondes servent à empêcher d’entendre la radio de l’Ouest.","aide":"Sa flèche pointillée attaque le signal de la radio.","type":"zone","document":"schema","multiple":false},{"enonce":"Touche le moyen de diffusion qui passe de main en main, sans radio ni presse officielle.","aide":"Des textes sont recopiés à la main.","type":"zone","document":"schema","multiple":false},{"enonce":"Associe chaque arme de l’information à son emploi.","aide":"Regarde d’où part chaque flèche du schéma.","type":"association","gauche":[{"id":"g0","texte":"Radios internationales"},{"id":"g1","texte":"Brouillage"},{"id":"g2","texte":"Samizdats"}],"droite":[{"id":"d0","texte":"Émettre par-delà le rideau de fer"},{"id":"d1","texte":"Des textes recopiés et diffusés clandestinement"},{"id":"d2","texte":"La riposte des régimes de l’Est"}]},{"enonce":"Que montre ce schéma sur l’information pendant la guerre froide ?","aide":"Observe qui émet, qui brouille et qui contourne.","type":"choix","options":[{"id":"a","texte":"Une disparition des radios au profit de la presse"},{"id":"b","texte":"Une information libre et partagée entre l’Est et l’Ouest"},{"id":"c","texte":"Un contrôle exercé seulement par les États de l’Ouest"},{"id":"d","texte":"Chaque camp veut contrôler ce qu’entend l’autre"}],"multiple":false}]}$ex$::jsonb,
