   $ex${"titre":"Reconnaître le contrôle de l’information","competence":"analyser-document","situation":"Yanis prépare un devoir : « Le contrôle de l’information appartient-il au passé ? ». Il compare deux grandes affaires du XXe siècle à un cas imaginaire de 2024.","documents":[{"id":"affaires","type":"tableau","titre":"Deux enquêtes qui ont fait vaciller un pouvoir","source":"D’après le cours.","colonnes":["Affaire","Date","Ce qui est révélé ou publié","Issue"],"lignes":[["Pentagon Papers","1971","Des documents classifiés sur la guerre du Vietnam","Publiés malgré le gouvernement"],["Watergate","1972-1974","L’enquête du Washington Post","Démission du président Nixon"]],"enteteLignes":true},{"id":"nord","type":"texte","genre":"article","titre":"En Nordmark, en 2024","auteur":"Texte écrit pour l’exercice : pays imaginaire","blocs":["Le ministère de la Communication exige de lire chaque article avant sa publication.","Le principal quotidien a été racheté par un proche du président.","Des milliers de faux comptes diffusent un faux document sur une opposante.","Le téléphone d’une journaliste d’investigation est espionné."]}],"questions":[{"enonce":"Touche l’affaire dont l’issue est la démission d’un président.","aide":"Regarde la colonne « Issue ».","type":"zone","document":"affaires","multiple":false},{"enonce":"Combien d’années séparent la publication des Pentagon Papers de la fin du Watergate ?","aide":"Prends l’année de la publication des Pentagon Papers et la dernière année du Watergate.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot qui montre qu’il s’agit d’une censure préalable.","aide":"Le contrôle intervient avant la parution.","type":"zone","document":"nord","multiple":false},{"enonce":"Associe chaque fait de Nordmark au mécanisme de contrôle qu’il illustre.","aide":"Relis chaque paragraphe de Nordmark : qui contrôle, comment ?","type":"association","gauche":[{"id":"g0","texte":"Lecture des articles avant parution"},{"id":"g1","texte":"Quotidien racheté par un proche du président"},{"id":"g2","texte":"Faux comptes qui diffusent un faux document"},{"id":"g3","texte":"Téléphone d’une journaliste espionné"}],"droite":[{"id":"d0","texte":"Censure directe"},{"id":"d1","texte":"Contrôle par la propriété"},{"id":"d2","texte":"Surveillance"},{"id":"d3","texte":"Campagne de désinformation"}]},{"enonce":"Que conclure de la comparaison entre 1971-1974 et Nordmark ?","aide":"Les formes changent, mais les mécanismes…","type":"choix","options":[{"id":"a","texte":"La presse n’a plus jamais été un contre-pouvoir"},{"id":"b","texte":"Le contrôle de l’information a disparu depuis le Watergate"},{"id":"c","texte":"Les mécanismes de contrôle de l’information n’appartiennent pas au passé"},{"id":"d","texte":"Seuls les régimes totalitaires du XXe siècle contrôlent l’information"}],"multiple":false}]}$ex$::jsonb,
