  ('8d788dd8-54b3-52c5-9fde-a04e5307cc41'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui nomme les évêques ?","competence":"analyser-texte","situation":"Zoé lit un récit sur la querelle des Investitures. Elle veut comprendre pourquoi un empereur s’humilie devant un pape, puis comment le conflit se règle.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le pape et l’empereur","auteur":"Récit rédigé pour l’exercice","blocs":["Au XIe siècle, le pape Grégoire VII veut que l’Église choisisse elle-même ses évêques. L’empereur Henri IV refuse : à ses yeux, ces évêques sont aussi de grands seigneurs, dont il a besoin.","Le pape excommunie Henri IV. Abandonné par une partie des princes allemands, l’empereur se rend en janvier 1077 au château de Canossa, en Italie, pour demander son pardon.","L’épisode reste le symbole d’un empereur humilié, mais la querelle ne s’arrête pas là : elle dure jusqu’au concordat de Worms, en 1122."]},{"id":"worms","type":"tableau","titre":"Le concordat de Worms (1122)","source":"D’après le cours.","colonnes":["Qui ?","Ce qu’il confère à l’évêque"],"lignes":[["L’Église","?"],["L’empereur","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le lieu qui symbolise l’humiliation de l’empereur Henri IV.","aide":"Le nom du château est dans le deuxième paragraphe.","type":"zone","document":"recit","multiple":false},{"enonce":"Combien d’années séparent Canossa du concordat de Worms ?","aide":"Soustrais 1077 à 1122.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi l’empereur tient-il tant à nommer les évêques ?","aide":"Relis la phrase qui explique les raisons d’Henri IV.","type":"choix","options":[{"id":"a","texte":"Il veut interdire la dîme aux paysans"},{"id":"b","texte":"Ce sont aussi de grands seigneurs temporels"},{"id":"c","texte":"Il souhaite supprimer le glaive spirituel"},{"id":"d","texte":"Il veut devenir lui-même prêtre"}],"multiple":false},{"enonce":"Complète le tableau : qui confère quelle investiture à Worms ?","aide":"Chaque pouvoir garde son domaine : spirituel pour l’Église, temporel pour l’empereur.","type":"association","gauche":[{"id":"g0","texte":"L’Église"},{"id":"g1","texte":"L’empereur"}],"droite":[{"id":"d0","texte":"L’investiture temporelle"},{"id":"d1","texte":"L’investiture spirituelle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m56"]},"explication":"**Canossa** : l’empereur y vient demander son pardon à Grégoire VII, un épisode resté fameux."},{"cle":{"type":"nombre","valeur":45,"tolerance":0},"affichage":"45 ans","explication":"1122 − 1077 = **45 ans** : la querelle des Investitures ne s’éteint pas avec Canossa."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les évêques sont aussi de **grands seigneurs temporels** : celui qui les nomme contrôle des terres et des hommes."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"À **Worms (1122)**, l’Église donne l’investiture **spirituelle**, l’empereur l’investiture **temporelle**. C’est un partage."}]$ex$::jsonb),
  ('8d788dd8-54b3-52c5-9fde-a04e5307cc41'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un évêque nommé par le roi","competence":"analyser-document","situation":"Nous sommes en 1520. Un évêque imaginaire écrit à un ami. Clara croise sa lettre avec une frise pour comprendre comment le roi de France en est arrivé là.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un évêque, en 1520","auteur":"Lettre imaginée, écrite pour l’exercice","blocs":["Mon cher ami, je dois ma charge au roi. Depuis l’accord signé en 1516 à Bologne, c’est lui qui nomme les évêques du royaume.","Je reste pourtant un homme d’Église : je baptise, je marie, je lève la dîme et je juge les clercs devant la justice de l’Église."]},{"id":"frise","type":"frise","titre":"Le roi, l’empereur et le pape","source":"D’après le cours.","debut":800,"fin":1600,"pas":200,"evenements":[{"id":"z1","date":800,"nom":"Sacre de Charlemagne"},{"id":"z2","date":1122,"nom":"Worms"},{"id":"z3","date":1303,"nom":"Boniface VIII arrêté"},{"id":"z4","date":1516,"nom":"Bologne"}]}],"questions":[{"enonce":"Touche le lieu de l’accord qui donne au roi la nomination des évêques.","aide":"Il est cité dans la première phrase de la lettre.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche l’événement où un roi de France fait arrêter un pape.","aide":"Philippe le Bel agit en 1303.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le concordat de Worms de celui de Bologne ?","aide":"Soustrais 1122 à 1516.","type":"nombre","unite":"ans"},{"enonce":"Comment appelle-t-on une Église catholique largement contrôlée par le pouvoir royal ?","aide":"Le mot vient d’un ancien nom de la France.","type":"choix","options":[{"id":"a","texte":"Le califat sunnite"},{"id":"b","texte":"La dîme royale"},{"id":"c","texte":"Le gallicanisme"},{"id":"d","texte":"Le millet ottoman"}],"multiple":false},{"enonce":"Range chaque pouvoir : appartient-il plutôt au roi ou à l’Église dans la lettre ?","aide":"Relis les deux paragraphes de la lettre.","type":"categories","categories":[{"id":"c0","texte":"Le roi"},{"id":"c1","texte":"L’Église"}],"items":[{"id":"i0","texte":"Nommer les évêques du royaume"},{"id":"i1","texte":"Baptiser et marier"},{"id":"i2","texte":"Juger les clercs devant sa propre justice"},{"id":"i3","texte":"Lever la dîme"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"C’est le **concordat de Bologne** (1516) : le roi de France y obtient la nomination des évêques."},{"cle":{"type":"zone","ids":["z3"]},"explication":"En **1303**, Philippe le Bel fait arrêter le pape **Boniface VIII** : l’État royal ne se laisse plus commander."},{"cle":{"type":"nombre","valeur":394,"tolerance":0},"affichage":"394 ans","explication":"1516 − 1122 = **394 ans** : l’équilibre entre pape, empereur et roi a beaucoup bougé."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est le **gallicanisme**. Le concordat de Bologne en est un jalon : le roi nomme les évêques."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1"}},"explication":"Le **roi** nomme les évêques ; l’**Église** garde la dîme, sa propre justice et les rites de la vie. Le pouvoir royal monte, sans effacer celui de l’Église."}]$ex$::jsonb),
