   $ex${"titre":"Démêler un conflit « religieux »","competence":"analyser-document","situation":"Dans un devoir, Anaïs doit analyser un conflit imaginaire où la religion est invoquée. Elle croise le récit du conflit avec les textes qui protègent la liberté de conscience.","documents":[{"id":"conflit","type":"texte","genre":"article","titre":"La vallée de l’Orme","auteur":"Texte écrit pour l’exercice : pays imaginaire","blocs":["En Karvélie, deux communautés, l’une de religion A, l’autre de religion B, s’affrontent depuis dix ans pour le contrôle de la vallée de l’Orme.","La vallée est fertile, et ses puits fournissent toute la région. Chaque camp y voit la terre de ses ancêtres, et un massacre commis en 1950 reste présent dans toutes les mémoires.","Le gouvernement, en difficulté, parle de « guerre sainte » pour rassembler la population derrière lui."]},{"id":"textes","type":"tableau","titre":"Deux garanties internationales","source":"D’après le cours.","colonnes":["Texte","Article","Ce qu’il garantit"],"lignes":[["Déclaration universelle des droits de l’homme (1948)","18","Liberté de pensée, de conscience et de religion"],["Convention européenne des droits de l’homme","9","Liberté de pensée, de conscience et de religion"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne une ressource en jeu dans le conflit.","aide":"La vallée fournit de l’eau à toute la région.","type":"zone","document":"conflit","multiple":false},{"enonce":"Range chaque élément selon l’enjeu qu’il révèle.","aide":"Un puits est une ressource, un massacre est un souvenir, un discours est un moyen de gouverner.","type":"categories","categories":[{"id":"c0","texte":"Ressources"},{"id":"c1","texte":"Mémoire"},{"id":"c2","texte":"Pouvoir"}],"items":[{"id":"i0","texte":"Les puits de la vallée"},{"id":"i1","texte":"La fertilité de la vallée"},{"id":"i2","texte":"Le discours de « guerre sainte » du gouvernement"},{"id":"i3","texte":"Le massacre de 1950"}]},{"enonce":"Quelle lecture du conflit est la plus juste ?","aide":"Relis les trois paragraphes : que se dispute-t-on vraiment ?","type":"choix","options":[{"id":"a","texte":"La religion y marque une identité mobilisée pour la terre, le pouvoir, la mémoire"},{"id":"b","texte":"C’est avant tout un affrontement entre deux doctrines religieuses opposées"},{"id":"c","texte":"Le conflit n’a aucun lien avec l’identité des deux communautés rivales"},{"id":"d","texte":"Le conflit est causé uniquement par une différence de langue entre les camps"}],"multiple":false},{"enonce":"Touche l’article de la Convention européenne des droits de l’homme qui garantit cette liberté.","aide":"Cherche la ligne « Convention européenne », colonne Article.","type":"zone","document":"textes","multiple":false},{"enonce":"Ces deux textes protègent aussi un droit particulier : lequel ?","aide":"Ils protègent la liberté de conscience, pas seulement le fait de croire.","type":"choix","options":[{"id":"a","texte":"Le droit d’imposer sa religion"},{"id":"b","texte":"Le droit de changer de religion"},{"id":"c","texte":"Le droit de ne payer aucun impôt"},{"id":"d","texte":"Le droit à une religion d’État"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"Les **puits** sont une ressource vitale : un enjeu matériel qui n’a rien de religieux."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c2","i3":"c1"}},"explication":"Puits et fertilité : **ressources** ; massacre : **mémoire** ; « guerre sainte » : **pouvoir** qui cherche à se légitimer."},{"cle":{"type":"choix","ids":["a"]},"explication":"Lire un conflit comme purement religieux est presque toujours une erreur : la religion est un **marqueur** mobilisé sur des enjeux de **terre, de pouvoir et de mémoire**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"C’est l’**article 9** de la Convention européenne des droits de l’homme ; la Déclaration universelle de 1948 le fait par son **article 18**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Ils garantissent la liberté de croire, de ne pas croire et **de changer de conviction** : un point refusé dans plusieurs États."}]$ex$::jsonb),
  ('0fa8840b-ea9b-536d-8ea9-d80ae5a10f47'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Quatre régimes en vingt-six ans","competence":"se-reperer-temps","situation":"Samia prépare une affiche pour son cours d’histoire. Elle veut montrer à ses camarades comment la France change de régime entre 1789 et 1815, et elle place les grands repères sur une frise.","documents":[{"id":"frise","type":"frise","titre":"La France de 1789 à 1815","source":"Repères du cours.","debut":1785,"fin":1815,"pas":5,"periodes":[{"id":"z1","debut":1791,"fin":1792,"nom":"Monarchie const.","teinte":"ambre"},{"id":"z2","debut":1792,"fin":1804,"nom":"République","teinte":"turquoise"},{"id":"z3","debut":1804,"fin":1815,"nom":"Empire","teinte":"rose"}],"evenements":[{"id":"z4","date":1789,"nom":"Droits de l’homme"},{"id":"z5","date":1793,"nom":"Mort de Louis XVI"},{"id":"z6","date":1804,"nom":"Sacre de Napoléon"},{"id":"z7","date":1815,"nom":"Waterloo"}]}],"questions":[{"enonce":"Touche l’événement qui proclame l’égalité des citoyens devant la loi.","aide":"Cet événement date de 1789 : c’est un texte.","type":"zone","document":"frise","multiple":false},{"enonce":"Louis XVI est guillotiné en janvier 1793. Touche la période pendant laquelle cette exécution a lieu.","aide":"Cherche le segment qui couvre l’année 1793.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la Déclaration des droits de l’homme du sacre de Napoléon ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Combien de régimes différents la frise montre-t-elle entre 1791 et 1815 ?","aide":"Compte les segments colorés.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"La **Déclaration des droits de l’homme et du citoyen** (26 août 1789) proclame l’égalité devant la loi."},{"cle":{"type":"zone","ids":["z2"]},"explication":"En 1793, la France est une **République** : elle a été proclamée en septembre 1792 et dure jusqu’en 1804."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 ans","explication":"1804 − 1789 = **15 ans**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"La frise montre **trois régimes** : la monarchie constitutionnelle, la République et l’Empire."}]$ex$::jsonb),
  ('0fa8840b-ea9b-536d-8ea9-d80ae5a10f47'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les premiers articles de 1789","competence":"analyser-texte","situation":"En classe, Malik lit deux articles de la Déclaration des droits de l’homme et du citoyen, votée en août 1789. Il doit y repérer ce qui change par rapport à la société d’ordres de l’Ancien Régime.","documents":[{"id":"ddhc","type":"texte","genre":"source","titre":"Deux articles de 1789","auteur":"Déclaration des droits de l’homme et du citoyen, 26 août 1789, articles 1 et 3","source":"Extraits recopiés du texte officiel.","blocs":["Art. 1er. Les hommes naissent et demeurent libres et égaux en droits. Les distinctions sociales ne peuvent être fondées que sur l’utilité commune.","Art. 3. Le principe de toute Souveraineté réside essentiellement dans la Nation. Nul corps, nul individu ne peut exercer d’autorité qui n’en émane expressément."]}],"questions":[{"enonce":"Touche le mot qui dit comment naissent les hommes, selon l’article 1 : libres et…","aide":"Cherche l’adjectif qui accompagne « libres ».","type":"zone","document":"ddhc","multiple":false},{"enonce":"Touche le mot qui désigne, d’après l’article 3, celui qui détient la souveraineté.","aide":"La souveraineté « réside » chez elle.","type":"zone","document":"ddhc","multiple":false},{"enonce":"Range chaque idée : la Révolution la supprime ou l’affirme ?","aide":"La nuit du 4 août abolit des droits ; la Déclaration en proclame d’autres.","type":"categories","categories":[{"id":"c0","texte":"Elle supprime"},{"id":"c1","texte":"Elle affirme"}],"items":[{"id":"i0","texte":"Les privilèges"},{"id":"i1","texte":"La souveraineté de la Nation"},{"id":"i2","texte":"La société d’ordres"},{"id":"i3","texte":"L’égalité devant la loi"}]},{"enonce":"Associe chaque date de 1789 à ce qui se passe.","aide":"Suis l’ordre du calendrier : l’Assemblée d’abord, la Déclaration à la fin.","type":"association","gauche":[{"id":"g0","texte":"17 juin"},{"id":"g1","texte":"14 juillet"},{"id":"g2","texte":"4 août"},{"id":"g3","texte":"26 août"}],"droite":[{"id":"d0","texte":"Les députés du tiers état se proclament Assemblée nationale"},{"id":"d1","texte":"Abolition des privilèges"},{"id":"d2","texte":"Prise de la Bastille"},{"id":"d3","texte":"Déclaration des droits de l’homme et du citoyen"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"Les hommes naissent et demeurent « libres et **égaux** en droits » : c’est le principe de l’égalité devant la loi."},{"cle":{"type":"zone","ids":["m35"]},"explication":"Le principe de toute souveraineté « réside essentiellement dans la **Nation** » : ce n’est plus le roi qui la détient. On parle de souveraineté nationale."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"La nuit du 4 août **supprime** les privilèges et donc la société d’ordres ; la Déclaration **affirme** l’égalité devant la loi et la souveraineté de la Nation."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"Le **17 juin** naît l’Assemblée nationale, le **14 juillet** la Bastille est prise, le **4 août** les privilèges sont abolis et le **26 août** la Déclaration est votée."}]$ex$::jsonb),
  ('0fa8840b-ea9b-536d-8ea9-d80ae5a10f47'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Napoléon garde-t-il la Révolution ?","competence":"analyser-document","situation":"Le professeur demande à Inès un bilan : que reste-t-il de 1789 sous Napoléon, et que devient l’Europe après ses conquêtes ? Elle dispose d’une carte et d’un tableau de synthèse.","documents":[{"id":"carte","type":"carte","titre":"Quelques lieux de l’Europe napoléonienne","source":"Frontières actuelles ; lieux repérés pour l’exercice.","fond":"europe","cadrage":[-6,40,28,56],"lieux":[{"id":"z1","lieu":"paris","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"vienne-autriche","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"londres","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"madrid","symbole":"lettre","lettre":"D"}]},{"id":"bilan","type":"tableau","titre":"Napoléon et l’héritage de 1789","source":"Synthèse du cours.","colonnes":["Principe","Sous Napoléon"],"lignes":[["Égalité devant la loi","Conservée (Code civil, 1804)"],["Fin des privilèges","Conservée"],["Liberté politique","Supprimée"]],"enteteLignes":true}],"questions":[{"enonce":"Le congrès de 1814-1815 qui redessine l’Europe se réunit dans la capitale de l’Autriche. Touche-la.","aide":"L’Autriche est à l’est de la France ; sa capitale porte le même nom que la ville du congrès.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la case qui dit ce que Napoléon supprime de l’héritage de 1789.","aide":"Une seule ligne du tableau parle d’une suppression.","type":"zone","document":"bilan","multiple":false},{"enonce":"Pourquoi les conquêtes napoléoniennes réveillent-elles le sentiment national des peuples d’Europe ?","aide":"Les idées de 1789 plaisent, mais pas la façon dont elles arrivent.","type":"choix","options":[{"id":"a","texte":"Parce que les principes diffusés s’accompagnent d’une domination imposée par la France"},{"id":"b","texte":"Parce que le Code civil est interdit dans tous les territoires conquis ou annexés"},{"id":"c","texte":"Parce que Napoléon rétablit partout l’ancienne société d’ordres du siècle passé"},{"id":"d","texte":"Parce que les peuples refusent de connaître l’égalité devant la loi des Français"}],"multiple":false},{"enonce":"Range ces événements dans l’ordre chronologique.","aide":"Pense aux années : 1789, 1792, 1799, 1804, 1815.","type":"ordre","items":[{"id":"a","texte":"Coup d’État du 18 brumaire"},{"id":"b","texte":"Prise de la Bastille"},{"id":"c","texte":"Bataille de Waterloo"},{"id":"d","texte":"Sacre de Napoléon"},{"id":"e","texte":"Proclamation de la République"}]}]}$ex$::jsonb,
