   $ex${"titre":"Une journée aux Tuileries","competence":"analyser-document","situation":"Le 10 août 1792, Paris se soulève. Lucas, élève de première, reconstitue le déroulement de cette journée à partir du tableau de son cours.","documents":[{"id":"journee","type":"tableau","titre":"La journée du 10 août 1792","source":"Tableau du cours.","colonnes":["Moment","Ce qui se passe"],"lignes":[["Nuit du 9 au 10 août","Les sections parisiennes forment une Commune insurrectionnelle"],["Matin","Les sans-culottes et les fédérés marchent sur les Tuileries"],["Vers 8 h","Le roi et sa famille se réfugient à l’Assemblée législative"],["Fin de matinée","Combat contre les gardes suisses"],["Soir","L’Assemblée suspend le roi et convoque une Convention"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le moment où Louis XVI se réfugie à l’Assemblée législative.","aide":"Cherche l’heure précise dans la première colonne.","type":"zone","document":"journee","multiple":false},{"enonce":"Qui marche sur les Tuileries le matin du 10 août ?","aide":"Relis la ligne du matin.","type":"choix","options":[{"id":"a","texte":"Les sans-culottes et les fédérés"},{"id":"b","texte":"Les prêtres réfractaires"},{"id":"c","texte":"Les armées de l’Autriche"},{"id":"d","texte":"Les gardes suisses et les nobles"}],"multiple":false},{"enonce":"Complète ce que décide l’Assemblée le soir.","aide":"La dernière ligne du tableau donne les deux mots.","type":"trous","segments":["Le soir, l’Assemblée ",0," le roi et convoque une ",1,"."],"banque":["condamne","Convention","Constituante","suspend"]}]}$ex$::jsonb,
