  ('d3e42820-407a-5f92-b0a0-d43cdde86736'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Lettre d’un fédéré marseillais","competence":"analyser-texte","situation":"Août 1792. Un jeune Marseillais imaginaire, Pierre, écrit à sa mère depuis Paris. Sa lettre et la chaîne des causes aident à comprendre pourquoi la monarchie tombe.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Pierre à sa mère, août 1792","source":"Lettre écrite pour l’exercice.","blocs":["Chère mère, nous sommes arrivés à Paris après des semaines de marche, nous les fédérés de Marseille, en chantant. Ici, les sans-culottes nous ont accueillis comme des frères.","On dit que le chef des armées prussiennes a menacé Paris si l’on touche au roi. Cela n’a fait qu’enflammer le peuple : demain, nous marcherons sur le palais des Tuileries, où vivent le roi et sa famille."]},{"id":"causes","type":"chaine","disposition":"colonne","titre":"Vers le 10 août 1792","noeuds":[{"id":"z1","texte":"Fuite à Varennes (juin 1791)"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Manifeste de Brunswick (juillet 1792)"},{"id":"z4","texte":"Prise des Tuileries (10 août 1792)"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le mot qui désigne les gardes nationaux venus des départements, comme les Marseillais.","aide":"Pierre dit qu’il en fait partie.","type":"zone","document":"lettre","multiple":false},{"enonce":"Quel événement d’avril 1792 manque dans la chaîne des causes ?","aide":"C’est la guerre extérieure qui commence en 1792.","type":"choix","options":[{"id":"a","texte":"L’exécution de Louis XVI"},{"id":"b","texte":"La victoire de Valmy"},{"id":"c","texte":"La proclamation de la République"},{"id":"d","texte":"La déclaration de guerre à l’Autriche"}],"multiple":false},{"enonce":"Quel effet le manifeste de Brunswick produit-il à Paris, d’après la lettre ?","aide":"Relis la phrase qui commence par « Cela n’a fait… ».","type":"choix","options":[{"id":"a","texte":"Il enflamme le peuple au lieu de l’effrayer"},{"id":"b","texte":"Il pousse les fédérés à rentrer chez eux"},{"id":"c","texte":"Il rassure les sans-culottes parisiens"},{"id":"d","texte":"Il convainc le roi de fuir à l’étranger"}],"multiple":false},{"enonce":"Range chaque acteur : il attaque ou il défend les Tuileries ?","aide":"Une seule force est du côté du roi.","type":"categories","categories":[{"id":"c0","texte":"Il attaque le palais"},{"id":"c1","texte":"Il défend le palais"}],"items":[{"id":"i0","texte":"La Commune insurrectionnelle"},{"id":"i1","texte":"Les fédérés marseillais"},{"id":"i2","texte":"Les sans-culottes"},{"id":"i3","texte":"Les gardes suisses"}]}]}$ex$::jsonb,
