  ('d3e42820-407a-5f92-b0a0-d43cdde86736'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"De la chute du roi à la République en guerre","competence":"se-reperer-espace","situation":"Après le 10 août 1792, tout va très vite. Camille doit situer sur une carte les lieux de cette période et relier les dates du tableau, pour expliquer pourquoi la République naît dans la guerre.","documents":[{"id":"carte","type":"carte","titre":"Lieux de la France révolutionnaire","source":"Carte réalisée pour l’exercice.","fond":"france","regionsCliquables":true,"lieux":[{"id":"z1","lieu":"paris","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lieu":"marseille","symbole":"lettre","lettre":"B","teinte":"violet"},{"id":"z3","lon":4.77,"lat":49.08,"symbole":"lettre","lettre":"C","teinte":"violet"}]},{"id":"dates","type":"tableau","titre":"Septembre 1792 – janvier 1793","source":"Repères du cours.","colonnes":["Date","Événement"],"lignes":[["20 septembre 1792","Victoire de Valmy, dans la Marne : les Prussiens sont arrêtés"],["22 septembre 1792","Début de la République"],["21 janvier 1793","Exécution de Louis XVI"],["1793","Guerre de Vendée"]],"enteteLignes":true}],"questions":[{"enonce":"Les fédérés qui participent à l’insurrection viennent notamment du grand port du Sud-Est. Touche-le.","aide":"C’est un port sur la Méditerranée.","type":"zone","document":"carte","multiple":false},{"enonce":"Valmy est un village de la Marne, à l’est de Paris. Touche sa lettre.","aide":"La Marne est en Champagne, entre Paris et la frontière du Nord-Est.","type":"zone","document":"carte","multiple":false},{"enonce":"La guerre intérieure éclate en 1793 en Vendée. Touche la région actuelle qui contient la Vendée.","aide":"La Vendée est sur la côte atlantique, au sud de la Bretagne.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien de jours séparent la victoire de Valmy du début de la République ?","aide":"Soustrais les deux jours de septembre.","type":"nombre","unite":"jours"},{"enonce":"Pourquoi l’exécution de Louis XVI pousse-t-elle les monarchies européennes à s’unir contre la France ?","aide":"Pense à ce que représente une République pour les rois.","type":"choix","options":[{"id":"a","texte":"Elles craignent que la Révolution ne se répande chez elles"},{"id":"b","texte":"Elles viennent de signer la paix avec la Convention"},{"id":"c","texte":"Elles veulent rétablir l’Empire de Napoléon"},{"id":"d","texte":"Elles sont déjà alliées à la République française"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La lettre **B** est Marseille : les fédérés marseillais popularisent le chant qui deviendra *La Marseillaise*."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**C** est Valmy, où la victoire du 20 septembre 1792 arrête l’avancée prussienne."},{"cle":{"type":"zone","ids":["PDL"]},"explication":"La Vendée est aujourd’hui dans la région des **Pays de la Loire**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 jours","explication":"22 − 20 = **2 jours** : Valmy a arrêté les Prussiens juste avant la proclamation de la République."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’exécution du roi inquiète les monarchies : elles forment une **coalition** contre une République qui menace leur ordre. La Terreur naît de cette guerre extérieure et de la guerre de Vendée."}]$ex$::jsonb),
