   $ex${"titre":"Les lois qui ouvrent l’école aux filles","competence":"lire-tableau","situation":"À la fin du XIXe siècle, la République veut instruire les filles. Camille, élève de première, lit un tableau des grandes lois qui construisent l’enseignement féminin.","documents":[{"id":"lois","type":"tableau","titre":"Les lois sur l’instruction des filles","source":"Tableau du cours.","colonnes":["Loi","Date","Contenu"],"lignes":[["Loi Camille Sée","21 décembre 1880","Crée l’enseignement secondaire public de jeunes filles"],["École normale supérieure de Sèvres","1881","Forme les professeures des lycées de filles"],["Lois Jules Ferry","1881-1882","École primaire gratuite, laïque et obligatoire de 6 à 13 ans"],["Loi Goblet","1886","Laïcise le personnel des écoles publiques"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la loi qui crée l’enseignement secondaire public de jeunes filles.","aide":"Cherche le mot « secondaire » dans la colonne « Contenu ».","type":"zone","document":"lois","multiple":false},{"enonce":"Jusqu’à quel âge l’école primaire est-elle obligatoire, pour les filles comme pour les garçons ?","aide":"Cherche les âges dans la ligne des lois Jules Ferry.","type":"nombre","unite":"ans"},{"enonce":"Que change la loi Goblet de 1886 dans les écoles publiques ?","aide":"Regarde la dernière ligne du tableau.","type":"choix","options":[{"id":"a","texte":"Elle rend l’école primaire gratuite"},{"id":"b","texte":"Elle laïcise le personnel enseignant"},{"id":"c","texte":"Elle crée un lycée par département"},{"id":"d","texte":"Elle supprime la formation des institutrices"}],"multiple":false}]}$ex$::jsonb,
