  ('f8e7da51-8647-5454-b117-9dda8785f94a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le journal de Jeanne, lycéenne en 1890","competence":"analyser-texte","situation":"Jeanne, lycéenne imaginaire, tient son journal en 1890. Son frère et elle ne suivent pas les mêmes études : il prépare le baccalauréat, elle prépare un diplôme de fin d’études.","documents":[{"id":"journal","type":"texte","genre":"lettre","titre":"Journal de Jeanne, 1890","source":"Texte écrit pour l’exercice.","blocs":["Cette année, au lycée de jeunes filles créé par la loi Camille Sée, nous avons des cours de couture et d’économie domestique, mais pas de latin ni de grec.","Mon frère prépare le baccalauréat, qui ouvre l’université. À la fin de mes cinq années, j’aurai un diplôme de fin d’études, qui n’y mène pas."]}],"questions":[{"enonce":"Touche le mot qui nomme l’examen que prépare le frère de Jeanne.","aide":"Il ouvre les portes de l’université.","type":"zone","document":"journal","multiple":false},{"enonce":"Combien d’années dure le secondaire des jeunes filles, d’après le journal ?","aide":"Relis la dernière phrase.","type":"nombre","unite":"ans"},{"enonce":"Range chaque élément : il concerne Jeanne ou son frère ?","aide":"Le journal dit ce que les filles n’étudient pas.","type":"categories","categories":[{"id":"c0","texte":"Le secondaire des filles"},{"id":"c1","texte":"Le secondaire des garçons"}],"items":[{"id":"i0","texte":"Latin et grec"},{"id":"i1","texte":"Cours de couture et d’économie domestique"},{"id":"i2","texte":"Diplôme de fin d’études"},{"id":"i3","texte":"Baccalauréat"}]},{"enonce":"Pourquoi les républicains veulent-ils instruire les filles ?","aide":"Les républicains pensent aux futures mères de famille.","type":"choix","options":[{"id":"a","texte":"Pour que toutes les écoles redeviennent confiées aux congrégations"},{"id":"b","texte":"Pour que les filles suivent les mêmes programmes que les garçons"},{"id":"c","texte":"Pour qu’elles obtiennent aussitôt le droit de vote et la citoyenneté complète"},{"id":"d","texte":"Pour les éloigner de l’influence de l’Église et former des mères républicaines"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m34"]},"explication":"Le **baccalauréat** ouvre l’université ; il faudra attendre 1924 pour que les programmes deviennent identiques pour les filles et les garçons."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 ans","explication":"Le secondaire féminin dure **cinq ans**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les filles étudient **couture et économie domestique** et reçoivent un **diplôme de fin d’études** ; les garçons étudient **latin et grec** et passent le **baccalauréat**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Pour les républicains, l’enjeu est politique : instruire les filles, c’est les arracher à l’**influence de l’Église** et former des **mères républicaines**."}]$ex$::jsonb),
  ('f8e7da51-8647-5454-b117-9dda8785f94a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Institutrice, un métier pour la République","competence":"analyser-document","situation":"Une jeune institutrice, imaginaire, écrit à une amie en 1900. Pour comprendre son quotidien, Élise place les grandes dates de l’instruction des filles sur une frise.","documents":[{"id":"frise","type":"frise","titre":"Instruire les filles, de 1861 à 1924","source":"Repères du cours.","debut":1860,"fin":1930,"pas":10,"evenements":[{"id":"z1","date":1861,"nom":"Première bachelière"},{"id":"z2","date":1880,"nom":"Loi Camille Sée"},{"id":"z3","date":1886,"nom":"Loi Goblet"},{"id":"z4","date":1924,"nom":"Programmes identiques"}]},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’une institutrice, 1900","source":"Lettre écrite pour l’exercice.","blocs":["Chère amie, me voici dans mon village. Je suis la première à y enseigner la morale laïque, et le curé ne me salue plus.","Le maire et l’inspecteur surveillent ma classe. On m’a dit que mon salaire resterait inférieur à celui de mon collègue instituteur."]}],"questions":[{"enonce":"Touche l’événement qui date de 1861 : Julie-Victoire Daubié est la première à décrocher ce diplôme.","aide":"Cherche le mot « bachelière ».","type":"zone","document":"frise","multiple":false},{"enonce":"Touche le mot qui désigne l’homme face à qui l’institutrice incarne la République.","aide":"Il représente l’Église dans le village.","type":"zone","document":"lettre","multiple":false},{"enonce":"Combien d’années séparent la loi Camille Sée de l’année où les programmes deviennent identiques ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Range ces lois dans l’ordre chronologique.","aide":"Les années vont de 1879 à 1886.","type":"ordre","items":[{"id":"a","texte":"Loi Goblet : personnel laïque"},{"id":"b","texte":"Lois Jules Ferry : école primaire obligatoire"},{"id":"c","texte":"Loi Camille Sée : secondaire public pour les filles"},{"id":"d","texte":"Loi Paul Bert : une école normale d’institutrices par département"}]},{"enonce":"Pourquoi dit-on que l’école forme des mères républicaines et non des citoyennes ?","aide":"Pense aux droits politiques des femmes à cette époque.","type":"choix","options":[{"id":"a","texte":"Parce que les institutrices ne sont pas payées"},{"id":"b","texte":"Parce que les filles quittent l’école avant six ans"},{"id":"c","texte":"Parce que le secondaire féminin est supprimé en 1924"},{"id":"d","texte":"Parce que les femmes n’ont pas le droit de vote"}],"multiple":false}]}$ex$::jsonb,
