  ('7b9d6028-669e-5cae-bdc2-29d28c1de3da'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les Jeunes Algériens réclament l’égalité","competence":"analyser-document","situation":"En 1912, un jeune Algérois imaginaire, formé à l’école française, écrit à un ami installé à Marseille. Sa lettre et une carte de la Méditerranée montrent les liens de la colonie avec la métropole.","documents":[{"id":"carte","type":"carte","titre":"Alger et la Méditerranée occidentale","source":"Carte réalisée pour l’exercice.","fond":"mediterranee","cadrage":[-8,33,12,45],"frontieres":true,"lieux":[{"id":"z1","lieu":"alger","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lieu":"marseille","symbole":"lettre","lettre":"B","teinte":"violet"},{"id":"z3","lieu":"tunis","symbole":"lettre","lettre":"C","teinte":"violet"},{"id":"z4","lieu":"rabat","symbole":"lettre","lettre":"D","teinte":"violet"}]},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un Jeune Algérien, 1912","source":"Lettre écrite pour l’exercice.","blocs":["Cher ami, je suis né à Alger et j’ai fait mes études dans une école française. Pourtant je suis sujet et non citoyen, soumis au code de l’indigénat et privé de droits politiques.","Avec d’autres jeunes instruits comme moi, nous réclamons l’égalité des droits entre tous les habitants."]}],"questions":[{"enonce":"Touche la ville de métropole reliée à Alger par des lignes maritimes régulières.","aide":"C’est un grand port du sud de la France.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la capitale de la Tunisie, entrée dans l’empire français en 1881.","aide":"Elle est à l’est de l’Algérie.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le mot qui nomme le statut du jeune homme, qu’il refuse de conserver.","aide":"Il le compare à celui de « citoyen ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Range chaque groupe d’habitants d’Alger : citoyen ou sujet ?","aide":"Un seul groupe n’a pas de droits politiques.","type":"categories","categories":[{"id":"c0","texte":"Citoyen français"},{"id":"c1","texte":"Sujet français"}],"items":[{"id":"i0","texte":"Les « indigènes » musulmans"},{"id":"i1","texte":"Les Européens naturalisés par la loi de 1889"},{"id":"i2","texte":"Les Français d’origine"},{"id":"i3","texte":"Les Juifs d’Algérie, depuis le décret Crémieux"}]},{"enonce":"Comment appelle-t-on, avant 1914, cette petite élite algérienne instruite en français qui réclame l’égalité des droits ?","aide":"Le titre de la lettre donne la réponse.","type":"texte"}]}$ex$::jsonb,
