   $ex${"titre":"Quatre ans de guerre sur une frise","competence":"se-reperer-temps","situation":"Pour l’anniversaire de l’armistice, la classe de Karim prépare une frise murale. Il doit y placer les repères essentiels de la Première Guerre mondiale, de l’attentat de Sarajevo au traité de Versailles.","documents":[{"id":"frise","type":"frise","titre":"De 1914 à 1919","source":"Repères du cours.","debut":1914,"fin":1920,"pas":1,"periodes":[{"id":"z1","debut":1914,"fin":1918,"nom":"La guerre","teinte":"corail"}],"evenements":[{"id":"z2","date":1914,"nom":"Sarajevo"},{"id":"z3","date":1916,"nom":"Verdun"},{"id":"z4","date":1918,"nom":"Armistice"},{"id":"z5","date":1919,"nom":"Versailles"}]}],"questions":[{"enonce":"Touche l’événement qui met fin aux combats.","aide":"Il est signé le 11 novembre 1918.","type":"zone","document":"frise","multiple":false},{"enonce":"Touche l’événement qui déclenche la crise de l’été 1914 : l’assassinat de l’archiduc François-Ferdinand.","aide":"Cherche le nom de la ville bosniaque.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’attentat de Sarajevo de l’armistice ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Quel traité de 1919 est imposé à l’Allemagne vaincue ?","aide":"Le nom de ce traité figure sur la frise.","type":"choix","options":[{"id":"a","texte":"Le traité de Brest-Litovsk"},{"id":"b","texte":"Le traité de Sèvres"},{"id":"c","texte":"Le traité de Trianon"},{"id":"d","texte":"Le traité de Versailles"}],"multiple":false}]}$ex$::jsonb,
