  ('745991fb-adf6-5ec4-bda5-c4091b8ba3af'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dans les tranchées, l’hiver 1915","competence":"analyser-texte","situation":"Hiver 1915. Un soldat français imaginaire écrit à sa famille depuis le front de l’Ouest. Son récit et le tableau des alliances montrent ce qu’est la guerre de position.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un soldat, décembre 1915","source":"Lettre écrite pour l’exercice.","blocs":["Chers parents, nous vivons dans les tranchées depuis des mois, dans la boue, face à l’ennemi. Le front ne bouge presque plus : on creuse, on attend, on se bat pour quelques mètres.","Les journaux disent que l’Italie nous a rejoints cet été. J’espère que cela hâtera la fin de la guerre."]},{"id":"camps","type":"tableau","titre":"Les deux camps en 1914-1918","source":"Tableau du cours.","colonnes":["Camp","Pays principaux"],"lignes":[["Triple-Entente (Alliés)","France, Royaume-Uni, Russie, puis Italie (1915), États-Unis (1917)"],["Puissances centrales","Allemagne, Autriche-Hongrie, Empire ottoman (1914), Bulgarie (1915)"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme les ouvrages creusés par les soldats pour se protéger.","aide":"Le soldat dit qu’il y vit « dans la boue ».","type":"zone","document":"lettre","multiple":false},{"enonce":"En quelle année l’Italie rejoint-elle l’Entente ?","aide":"La ligne « Triple-Entente » du tableau donne l’année.","type":"nombre"},{"enonce":"Range ces pays dans leur camp.","aide":"Relis chaque ligne du tableau.","type":"categories","categories":[{"id":"c0","texte":"Triple-Entente"},{"id":"c1","texte":"Puissances centrales"}],"items":[{"id":"i0","texte":"Empire ottoman"},{"id":"i1","texte":"Russie"},{"id":"i2","texte":"Allemagne"},{"id":"i3","texte":"France"}]},{"enonce":"Range ces moments de la guerre dans l’ordre chronologique.","aide":"Pense à 1914, 1916, 1917, 1918.","type":"ordre","items":[{"id":"a","texte":"Batailles de Verdun et de la Somme"},{"id":"b","texte":"Entrée en guerre des États-Unis"},{"id":"c","texte":"Attentat de Sarajevo"},{"id":"d","texte":"Bataille de la Marne"},{"id":"e","texte":"Armistice"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"Les **tranchées** se creusent de la mer du Nord à la Suisse : c’est la guerre de position (1915-1917)."},{"cle":{"type":"nombre","valeur":1915,"tolerance":0},"affichage":"1915","explication":"L’Italie entre en guerre aux côtés des Alliés en **1915**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**France** et **Russie** appartiennent à l’Entente ; **Allemagne** et **Empire ottoman** aux puissances centrales."},{"cle":{"type":"ordre","ids":["c","d","a","b","e"]},"explication":"Sarajevo (**juin 1914**), Marne (**septembre 1914**), Verdun et Somme (**1916**), États-Unis (**avril 1917**), armistice (**11 novembre 1918**)."}]$ex$::jsonb),
  ('745991fb-adf6-5ec4-bda5-c4091b8ba3af'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une paix difficile","competence":"analyser-document","situation":"En 1919-1920, la conférence de la paix fixe le sort des vaincus. Alice étudie le tableau des traités et un texte sur l’une des plus grandes tragédies de la guerre : le génocide des Arméniens.","documents":[{"id":"traites","type":"tableau","titre":"Les traités de paix","source":"Tableau du cours.","colonnes":["Traité","Date","Pays vaincu"],"lignes":[["Versailles","28 juin 1919","Allemagne"],["Saint-Germain-en-Laye","10 septembre 1919","Autriche"],["Trianon","4 juin 1920","Hongrie"],["Sèvres","10 août 1920","Empire ottoman"]],"enteteLignes":true},{"id":"genocide","type":"texte","genre":"article","titre":"Le génocide des Arméniens","source":"Texte rédigé pour l’exercice, d’après le cours.","blocs":["Un génocide est l’extermination organisée d’un peuple parce qu’il est ce peuple.","En 1915-1916, le gouvernement jeune-turc de l’Empire ottoman organise des massacres et des déportations : environ 1,2 million d’Arméniens meurent, soit les deux tiers des Arméniens de l’empire."]}],"questions":[{"enonce":"Touche le traité qui est imposé à l’Allemagne.","aide":"Cherche l’Allemagne dans la colonne « Pays vaincu ».","type":"zone","document":"traites","multiple":false},{"enonce":"Touche le pays vaincu qui voit disparaître son empire multinational, signataire de Sèvres.","aide":"Sèvres est la dernière ligne.","type":"zone","document":"traites","multiple":false},{"enonce":"1,2 million de morts représentent les deux tiers des Arméniens de l’empire. Combien d’Arméniens vivaient dans l’empire, en millions ?","aide":"Si deux tiers valent 1,2 million, un tiers vaut 0,6 million.","type":"nombre","unite":"millions"},{"enonce":"Pourquoi parle-t-on de génocide pour les Arméniens ?","aide":"Relis la première phrase du texte.","type":"choix","options":[{"id":"a","texte":"Parce que c’est la plus grande bataille de la guerre"},{"id":"b","texte":"Parce que l’armée ottomane perd la guerre en 1918"},{"id":"c","texte":"Parce que des soldats arméniens désertent le front"},{"id":"d","texte":"Parce qu’un peuple est exterminé en raison de ce qu’il est"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"Le traité de **Versailles** (28 juin 1919) est imposé à l’Allemagne."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"L’**Empire ottoman** signe le traité de Sèvres ; il fait partie des quatre empires qui disparaissent."},{"cle":{"type":"nombre","valeur":1.8,"tolerance":0},"affichage":"1,8 millions","explication":"Un tiers = 1,2 ÷ 2 = 0,6 million ; le tout vaut 3 × 0,6 = **1,8 million**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un génocide est l’**extermination organisée d’un peuple** parce qu’il est ce peuple : c’est le premier génocide du XXe siècle."}]$ex$::jsonb),
  ('dadd27d5-a739-58f6-9736-488e661a42be'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une armée venue du monde entier","competence":"lire-tableau","situation":"À l’été 1916, des soldats de nombreux pays se retrouvent en Picardie. Paul lit un tableau pour comprendre qui combat sur la Somme et qui travaille derrière les lignes.","documents":[{"id":"armees","type":"tableau","titre":"Qui participe à la bataille de la Somme ?","source":"Tableau du cours.","colonnes":["Participants","Origine"],"lignes":[["Armée britannique (général Haig)","Royaume-Uni, Canadiens, Terre-Neuviens, Australiens, Néo-Zélandais, Sud-Africains, soldats de l’Inde"],["Armée française (général Foch)","Métropolitains, tirailleurs sénégalais, soldats d’Afrique du Nord"],["Main-d’œuvre de l’arrière","Travailleurs chinois et travailleurs coloniaux"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le général qui commande l’armée française.","aide":"Cherche la ligne « Armée française ».","type":"zone","document":"armees","multiple":false},{"enonce":"Quels travailleurs sont recrutés pour la main-d’œuvre de l’arrière ?","aide":"Regarde la dernière ligne du tableau.","type":"choix","options":[{"id":"a","texte":"Des ouvriers suisses envoyés par leur gouvernement"},{"id":"b","texte":"Des soldats australiens venus par bateau"},{"id":"c","texte":"Des travailleurs chinois et des travailleurs coloniaux"},{"id":"d","texte":"Des prisonniers allemands libérés pour l’occasion"}],"multiple":false},{"enonce":"Que montre la variété des origines de ces soldats ?","aide":"Compte les continents d’où viennent les soldats.","type":"choix","options":[{"id":"a","texte":"La guerre reste une affaire entre la France et l’Allemagne"},{"id":"b","texte":"Les soldats coloniaux restent loin des champs de bataille"},{"id":"c","texte":"La guerre est mondiale : elle mobilise des empires entiers"},{"id":"d","texte":"Les armées britannique et française sont identiques"}],"multiple":false}]}$ex$::jsonb,
