  ('dadd27d5-a739-58f6-9736-488e661a42be'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Sur le front de la Somme","competence":"lire-carte","situation":"La bataille de la Somme s’est déroulée en Picardie. Sarah situe sur une carte les lieux de mémoire à visiter, puis calcule combien de temps la bataille a duré.","documents":[{"id":"carte","type":"carte","titre":"La Picardie en 1916","source":"Carte réalisée pour l’exercice, ligne du front simplifiée.","fond":"france","cadrage":[1.8,49.5,3.6,50.4],"lieux":[{"id":"z1","lon":2.65,"lat":50,"symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lon":2.93,"lat":49.93,"symbole":"lettre","lettre":"B","teinte":"violet"},{"id":"z3","lieu":"amiens","symbole":"point","nom":"Amiens"}],"traits":[{"id":"z4","points":[[2.62,50.12],[2.82,49.96]],"style":"pointilles","teinte":"corail","epaisseur":2}],"legende":[{"teinte":"corail","texte":"Le front, vers juillet 1916"}]},{"id":"dates","type":"tableau","titre":"Dates de l’année 1916","source":"Repères du cours.","colonnes":["Date","Événement"],"lignes":[["21 février 1916","Début de la bataille de Verdun"],["1er juillet 1916","Début de la bataille de la Somme"],["18 novembre 1916","Fin de la bataille de la Somme"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ville de Péronne, où se trouve l’Historial de la Grande Guerre, à l’est de la ligne du front.","aide":"Le front sépare les deux lettres : Péronne est du côté opposé à Amiens.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche Albert, ville proche du cratère de Lochnagar, à l’ouest du front.","aide":"Albert est du côté d’Amiens, à l’ouest de la ligne.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ligne du front, qui coupe la vallée de la Somme entre Albert et Péronne.","aide":"Elle passe entre les deux lettres.","type":"zone","document":"carte","multiple":false},{"enonce":"Du 1er juillet au 18 novembre 1916, il s’écoule 140 jours. Combien de semaines complètes dure la bataille ?","aide":"Divise 140 par 7.","type":"nombre","unite":"semaines"},{"enonce":"Pourquoi les Britanniques fournissent-ils l’essentiel de l’effort sur la Somme ?","aide":"Regarde ce qui commence le 21 février 1916.","type":"choix","options":[{"id":"a","texte":"Parce que la France engage ses forces à Verdun"},{"id":"b","texte":"Parce que Foch refuse de commander l’offensive"},{"id":"c","texte":"Parce que la France a quitté la guerre en 1916"},{"id":"d","texte":"Parce que l’Allemagne ne défend pas ce secteur"}],"multiple":false}]}$ex$::jsonb,
