dun de celui de la Somme ?","aide":"Compare février et juillet 1916.","type":"choix","options":[{"id":"a","texte":"Environ deux semaines"},{"id":"b","texte":"Environ vingt jours"},{"id":"c","texte":"Environ un an et demi"},{"id":"d","texte":"Environ quatre mois"}],"multiple":false},{"enonce":"Pourquoi dit-on que le 1er juillet 1916 est le jour le plus meurtrier de l’armée britannique ?","aide":"Regarde la ligne du 1er juillet dans la chronologie.","type":"choix","options":[{"id":"a","texte":"Plus d’un million de soldats britanniques y meurent"},{"id":"b","texte":"Près de 20 000 soldats britanniques y meurent en une journée"},{"id":"c","texte":"Les chars d’assaut y font leurs premières victimes"},{"id":"d","texte":"La bataille se termine ce jour-là par un armistice"}],"multiple":false}]}$ex$::jsonb,
