   $ex${"titre":"Après 1919, l’Europe centrale en morceaux","competence":"analyser-document","situation":"Camille compare la carte de l’Europe centrale après la guerre au résumé du traité de Saint-Germain. Elle veut comprendre pourquoi la région reste instable.","documents":[{"id":"carte","type":"carte","titre":"Quelques villes de l’ancien empire","fond":"europe","frontieres":true,"source":"Frontières d’aujourd’hui ; villes citées dans le cours.","cadrage":[6,41,26,52],"lieux":[{"id":"z1","lieu":"vienne-autriche","nom":"Vienne","symbole":"point"},{"id":"z2","lieu":"prague","nom":"Prague","symbole":"point"},{"id":"z3","lieu":"budapest","nom":"Budapest","symbole":"point"},{"id":"z4","lieu":"belgrade","nom":"Belgrade","symbole":"point"},{"id":"z5","lon":13.77,"lat":45.65,"nom":"Trieste","symbole":"point"}]},{"id":"traite","type":"texte","genre":"article","titre":"Ce que dit le traité de Saint-Germain (1919)","source":"Résumé écrit pour l’exercice, d’après le cours.","blocs":["L’Autriche, réduite à environ 6,5 millions d’habitants, reconnaît l’indépendance des nouveaux États.","Elle cède le Tyrol du Sud et Trieste à l’Italie, la Galicie à la Pologne, la Bohême et la Moravie à la Tchécoslovaquie.","Il lui est interdit de s’unir à l’Allemagne : cette union s’appelle l’Anschluss."]}],"questions":[{"enonce":"Touche la ville portuaire que l’Autriche cède à l’Italie.","aide":"Relis la deuxième phrase du traité, puis cherche un port sur l’Adriatique.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la capitale de la Tchécoslovaquie, qui reçoit la Bohême et la Moravie.","aide":"La Bohême est le cœur historique du nouvel État.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le mot qui désigne l’union avec l’Allemagne, interdite à l’Autriche.","aide":"C’est un mot allemand, dans la dernière phrase.","type":"zone","document":"traite","multiple":false},{"enonce":"Associe chaque accord à ce qu’il règle.","aide":"Un armistice arrête les combats ; un traité règle le sort d’un pays.","type":"association","gauche":[{"id":"g0","texte":"Villa Giusti (3 novembre 1918)"},{"id":"g1","texte":"Saint-Germain-en-Laye (1919)"},{"id":"g2","texte":"Trianon (1920)"}],"droite":[{"id":"d0","texte":"L’armistice de l’Autriche-Hongrie"},{"id":"d1","texte":"Le sort de la Hongrie"},{"id":"d2","texte":"Le sort de l’Autriche"}]},{"enonce":"Pourquoi la région reste-t-elle une zone de tension après 1919 ?","aide":"Pense aux peuples qui se retrouvent dans un État qui n’est pas le leur.","type":"choix","options":[{"id":"a","texte":"La Hongrie a été agrandie et défend ses nouveaux territoires"},{"id":"b","texte":"L’Autriche-Hongrie a été reconstituée en secret par les vainqueurs de 1919"},{"id":"c","texte":"Tous les nouveaux États sont devenus des dictatures dès l’année 1919"},{"id":"d","texte":"Les frontières ne suivent pas les peuples : chaque État garde des minorités"}],"multiple":false}]}$ex$::jsonb,
