  ('f77244d8-0dae-59eb-beb4-44e1ee8cd745'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trois habitants, trois façons de vivre Lyon","competence":"analyser-document","situation":"Une journaliste recueille trois portraits d’habitants de la métropole lyonnaise, tous imaginaires. Elle les croise avec leur temps de trajet pour montrer les contrastes de la ville.","documents":[{"id":"portraits","type":"texte","genre":"recit","titre":"Trois portraits","source":"Portraits écrits pour l’exercice, personnages imaginaires.","blocs":["Léo est ingénieur dans une tour de la Part-Dieu. Il habite à la Croix-Rousse, où les loyers ont beaucoup monté : des familles modestes sont parties et des cadres s’installent. C’est la gentrification.","Samia est aide-soignante. Elle vit aux Minguettes, à Vénissieux, dans un logement social en partie rénové, et rejoint la Part-Dieu en transports en commun.","Hugo travaille à la Part-Dieu mais habite un lotissement de la Plaine de l’Ain, où il a trouvé une maison plus grande pour le même prix. Il fait la navette tous les jours."]},{"id":"trajets","type":"tableau","titre":"Trajets vers la Part-Dieu","source":"Durées imaginées pour l’exercice.","colonnes":["Habitant","Domicile","Mode de transport","Durée (min)"],"lignes":[["Léo","La Croix-Rousse","Métro",20],["Samia","Vénissieux","Tramway et métro",35],["Hugo","Plaine de l’Ain","Voiture",60]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne l’installation de ménages aisés dans un quartier populaire.","aide":"Il se trouve dans le portrait de Léo, après « C’est la ».","type":"zone","document":"portraits","multiple":false},{"enonce":"Touche la case qui indique comment l’habitant du périurbain se rend à la Part-Dieu.","aide":"Repère qui habite en périurbain dans les portraits, puis lis sa ligne.","type":"zone","document":"trajets","multiple":false},{"enonce":"Combien de minutes de plus que Léo Hugo passe-t-il dans ses trajets, à chaque aller ?","aide":"Soustrais la plus petite durée à la plus grande.","type":"nombre","unite":"min"},{"enonce":"Associe chaque habitant à l’espace où il vit.","aide":"Reprends le domicile de chaque personnage dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"Léo"},{"id":"g1","texte":"Samia"},{"id":"g2","texte":"Hugo"}],"droite":[{"id":"d0","texte":"Un quartier populaire de l’Est"},{"id":"d1","texte":"Un quartier central gentrifié"},{"id":"d2","texte":"Une commune périurbaine"}]},{"enonce":"Que montrent ces trois portraits pris ensemble ?","aide":"Compare les trois lieux de vie : sont-ils semblables ?","type":"choix","options":[{"id":"a","texte":"Les quartiers populaires ont disparu de la métropole lyonnaise"},{"id":"b","texte":"Tous les habitants de la métropole vivent à moins de vingt minutes"},{"id":"c","texte":"La métropolisation de Lyon crée de forts contrastes socio-spatiaux"},{"id":"d","texte":"L’étalement urbain s’est arrêté autour de la métropole"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m33"]},"explication":"La **gentrification** transforme un quartier populaire : les loyers montent et les habitants modestes partent."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Hugo habite en périurbain : il se déplace en **voiture**, ce qui rend la navette longue."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 min","explication":"60 − 20 = **40 minutes** de plus : l’étalement urbain allonge les déplacements."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Léo vit à la Croix-Rousse (**gentrification**), Samia à Vénissieux (**quartier populaire**), Hugo dans la Plaine de l’Ain (**périurbain**)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Entre quartier gentrifié, quartier populaire et périurbain, les écarts sont grands : c’est la **fragmentation socio-spatiale** de la métropole."}]$ex$::jsonb),
