   $ex${"titre":"Quarante ans de chantiers à Londres","competence":"se-reperer-temps","situation":"Zoé visite Londres avec sa classe. Sur une frise, elle place les grandes opérations qui ont transformé la ville depuis 1981, puis elle cherche ce que chacune a changé.","documents":[{"id":"frise","type":"frise","titre":"Londres se transforme, 1980-2025","source":"Frise établie d’après le cours.","debut":1980,"fin":2025,"pas":5,"evenements":[{"id":"z1","date":1981,"nom":"Docklands rénovés"},{"id":"z2","date":2000,"nom":"Tate Modern"},{"id":"z3","date":2012,"nom":"Jeux olympiques"},{"id":"z4","date":2020,"nom":"Sortie de l’UE"}]}],"questions":[{"enonce":"Touche l’événement qui a servi à rénover l’Est londonien, autour de Stratford.","aide":"Un grand événement sportif accueille des parcs, des logements et des équipements.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le début de la réhabilitation des Docklands de l’ouverture de la Tate Modern ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque événement à ce qu’il a changé.","aide":"Pour la sortie de l’Union européenne, pense à la finance.","type":"association","gauche":[{"id":"g0","texte":"Docklands rénovés (1981)"},{"id":"g1","texte":"Tate Modern (2000)"},{"id":"g2","texte":"Jeux olympiques (2012)"},{"id":"g3","texte":"Sortie de l’UE (2020)"}],"droite":[{"id":"d0","texte":"Un quartier d’affaires et résidentiel autour de Canary Wharf"},{"id":"d1","texte":"Un musée installé dans une ancienne centrale électrique"},{"id":"d2","texte":"Le départ de certaines activités financières"},{"id":"d3","texte":"La rénovation de l’Est londonien"}]},{"enonce":"Depuis la sortie de l’Union européenne, quelle est la situation de la City ?","aide":"Le cours parle d’activités déplacées, pas d’une disparition.","type":"choix","options":[{"id":"a","texte":"Elle a déménagé de Londres pour s’installer entièrement à Paris et à Francfort"},