   $ex${"titre":"Le site, la situation et le trajet des conteneurs","competence":"analyser-document","situation":"Un guide présente Rotterdam à des lycéens. Pour qu’ils retiennent l’essentiel, il leur demande de distinguer ce qui fait la qualité du site de ce qui fait celle de la situation, puis de suivre le trajet des marchandises.","documents":[{"id":"guide","type":"texte","genre":"article","titre":"Le port vu par un guide","source":"Texte écrit pour l’exercice, d’après le cours.","blocs":["Rotterdam s’est installée à l’embouchure du Rhin et de la Meuse, au bord de la mer du Nord. Ses eaux profondes accueillent les plus grands navires.","Le port se trouve au cœur de la Northern Range, au débouché de l’hinterland le plus riche d’Europe : Pays-Bas, Allemagne rhénane, Belgique, nord de la France, Suisse.","Chaque jour, des convois repartent vers l’intérieur : barges sur le Rhin, trains sur la Betuweroute, camions et oléoducs."]},{"id":"repartition","type":"graphique","forme":"secteurs","titre":"Comment repartent 100 conteneurs de Rotterdam ?","source":"Répartition imaginée pour l’exercice.","categories":["Route","Barges fluviales","Rail"],"series":[{"nom":"Part des conteneurs","valeurs":[45,35,20]}]}],"questions":[{"enonce":"Touche le mot qui désigne la zone d’influence d’un port à l’intérieur des terres.","aide":"Il se trouve dans le deuxième paragraphe.","type":"zone","document":"guide","multiple":false},{"enonce":"Range chaque phrase : parle-t-elle du site ou de la situation ?","aide":"Le site, c’est le lieu précis ; la situation, c’est la position par rapport aux régions voisines.","type":"categories","categories":[{"id":"c0","texte":"Le site"},{"id":"c1","texte":"La situation"}],"items":[{"id":"i0","texte":"À l’embouchure du Rhin et de la Meuse"},{"id":"i1","texte":"Au cœur de la Northern Range"},{"id":"i2","texte":"Au débouché de l’hinterland le plus riche d’Europe"},{"id":"i3","texte":"Des eaux profondes pour les plus grands navires"}]},{"enonce":"Sur 2 000 conteneurs, combien repartent par barge fluviale ?","aide":"Calcule 35 % de 2 000.","type":"nombre","unite":"conteneurs"},{"enonce":"Quel mot désigne un espace où se côtoient port, raffineries, chimie et logistique ?","aide":"Le sigle est ZIP.","type":"choix","options":[{"id":"a","texte":"Un technopôle de recherche"},{"id":"b","texte":"Une mégalopole côtière"},{"id":"c","texte":"Un quartier d’affaires"},{"id":"d","texte":"Une zone industrialo-portuaire"}],"multiple":false}]}$ex$::jsonb,
