 croissance démographique ?","aide":"Des citadins y cherchent une maison et un cadre de vie.","type":"choix","options":[{"id":"a","texte":"Le rural vivrier"},{"id":"b","texte":"Le rural périurbain"},{"id":"c","texte":"Le rural abandonné"},{"id":"d","texte":"Le rural isolé"}],"multiple":false}]}$ex$::jsonb,
