  ('3a8214cc-0b63-5629-8e40-5f67e2aa6035'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux paysans, deux mondes","competence":"analyser-document","situation":"Pierre cultive des céréales en Beauce, Awa du mil au Mali. Leurs témoignages, imaginaires, permettent de comparer les campagnes d’un pays riche et celles d’un pays en développement.","documents":[{"id":"temoins","type":"texte","genre":"recit","titre":"Deux témoignages","source":"Témoignages écrits pour l’exercice, personnages imaginaires.","blocs":["Pierre : « Je cultive du blé en Beauce avec deux salariés et de gros tracteurs. Nous sommes de moins en moins nombreux dans la région, mais nous produisons beaucoup, et une grande part de notre blé part à l’exportation. »","Awa : « Je cultive du mil sur un petit champ avec ma famille. Nous mangeons une partie de la récolte et je vends le reste au marché du village. Mon fils aîné est parti travailler à Bamako : c’est l’exode de beaucoup de jeunes. »"]},{"id":"exploitations","type":"tableau","titre":"Deux exploitations comparées","source":"Données imaginées pour l’exercice.","colonnes":["Critère","Pierre (Beauce)","Awa (Mali)"],"lignes":[["Surface cultivée","250 hectares","2 hectares"],["Main-d’œuvre","Pierre et deux salariés","Toute la famille"],["Débouché","Exportation de blé","Repas de la famille et marché local"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne le départ des jeunes des campagnes vers les villes.","aide":"Il est dans le témoignage d’Awa, à propos de son fils.","type":"zone","document":"temoins","multiple":false},{"enonce":"Touche la case qui montre que l’agriculture d’Awa est surtout vivrière.","aide":"Une agriculture vivrière nourrit d’abord la famille.","type":"zone","document":"exploitations","multiple":false},{"enonce":"Combien de fois la surface cultivée par Pierre est-elle plus grande que celle d’Awa ?","aide":"Divise 250 par 2.","type":"nombre","unite":"fois"},{"enonce":"Range ces caractéristiques selon le type de pays.","aide":"Reprends les deux témoignages un par un.","type":"categories","categories":[{"id":"c0","texte":"Pays riches"},{"id":"c1","texte":"Pays en développement"}],"items":[{"id":"i0","texte":"Agriculture vivrière et exode rural"},{"id":"i1","texte":"Peu d’agriculteurs, très productifs"},{"id":"i2","texte":"Population rurale nombreuse"},{"id":"i3","texte":"Agriculture tournée vers l’exportation"}]}]}$ex$::jsonb,
