  ('fc8984b9-2160-5d1a-aa2c-3ff2d055f7ce'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Mathieu, des Hauts de La Réunion au bureau","competence":"analyser-document","situation":"Mathieu, technicien imaginaire à Saint-Pierre, vit dans les Hauts de La Réunion. Son témoignage et son budget de trajet montrent comment la périurbanisation s’étend aussi dans les outre-mer.","documents":[{"id":"mathieu","type":"texte","genre":"recit","titre":"Le témoignage de Mathieu","source":"Texte écrit pour l’exercice, personnage imaginaire.","blocs":["Mathieu travaille à Saint-Pierre, sur le littoral. Faute de terrain abordable en bas, il a fait construire sa maison dans les Hauts, sur d’anciennes terres de canne à sucre.","Chaque jour, il descend vers le littoral en voiture. Quand le prix du carburant monte, son budget s’alourdit : le mouvement des « gilets jaunes », en 2018, est parti en partie de ces espaces dépendants de la voiture.","Autour de chez lui, de nouveaux lotissements grignotent encore les champs."]},{"id":"budget","type":"tableau","titre":"Le trajet quotidien de Mathieu","source":"Données imaginées pour l’exercice.","colonnes":["Donnée","Valeur"],"lignes":[["Distance aller","28 km"],["Trajets par jour","2 (aller et retour)"],["Jours travaillés par an","220"],["Consommation de la voiture","7 L pour 100 km"],["Prix du carburant","1,80 € le litre"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne les pentes au-dessus des villes littorales où progresse la périurbanisation.","aide":"Il est dans le premier paragraphe, avec une majuscule.","type":"zone","document":"mathieu","multiple":false},{"enonce":"Combien de kilomètres Mathieu parcourt-il en une année de travail ?","aide":"Multiplie la distance aller par le nombre de trajets, puis par le nombre de jours.","type":"nombre","unite":"km"},{"enonce":"Combien dépense-t-il en carburant par an pour ces trajets ? Arrondis à l’euro.","aide":"Calcule d’abord les litres : 12 320 km à 7 L pour 100 km. Multiplie ensuite par le prix du litre.","type":"nombre","unite":"€"},{"enonce":"Pourquoi les conflits d’usage sont-ils plus forts dans les outre-mer, comme à La Réunion ?","aide":"Pense à la forme d’une île volcanique : montagne au centre, littoral étroit.","type":"choix","options":[{"id":"a","texte":"Les villes ne s’y étendent jamais vers l’intérieur"},{"id":"b","texte":"Le relief et le littoral limitent l’espace disponible"},{"id":"c","texte":"Il n’y a pas de terres agricoles à protéger"},{"id":"d","texte":"La loi interdit toute construction dans les Hauts"}],"multiple":false}]}$ex$::jsonb,
